/* Fixed artwork comes from the user's original PDFs. Dynamic report content is rebuilt. */
(function(root){
const meta={
 'PM-FP-001':{key:'pm151',code:'PM.FP.69-151',title:'Preventive Maintenance',pages:56,performancePage:44,landscapePage:43},
 'PT-FP-001':{key:'pt095',code:'PM.FP.69-095',title:'Performance Test',pages:44,performancePage:26,landscapePage:25}
};
function get(p){return meta[p.template]||meta['PM-FP-001']}
function render(c){const {s,p,esc:e,questions,photos,urls,pageNo,total,answerLabel,testTable,chart,formatDate}=c,m=get(p);const company=p.report_customer_line||`${p.customer}${p.site?' ('+p.site+')':''}`;const code=e(p.code);let content='';const head=`<header class="classic-head"><img src="assets/templates/pakorn-logo.png" alt="PAKORN Technical Supply"><div><b><i>Fire Pump System Preventive Maintenance</i></b><strong>${e(company)}</strong></div></header>`;
if(s==='cover')return `<article class="paper classic-paper classic-cover" data-template="${m.key}" aria-label="หน้าปกตามต้นฉบับ ${m.code}"><img class="classic-cover-art" src="assets/templates/${m.key}/cover-base.png" alt="กราฟิกปกต้นฉบับ Pakorn"><div class="classic-cover-heading">Fire Pump System</div><div class="classic-cover-subtitle">${m.title}</div><div class="classic-cover-customer">${e(company)}</div><div class="classic-cover-code">${code}</div></article>`;
if(s==='inspection'){content=`<h2>หมวดที่ 1</h2><h3>การตรวจสอบพื้นที่ การติดตั้งและสภาพอุปกรณ์ระบบเครื่องยนต์ดับเพลิง</h3><table class="classic-photo-table"><thead><tr><th colspan="2">ห้องควบคุมระบบเครื่องยนต์ดับเพลิง (Fire Pump Room)</th></tr></thead><tbody><tr>${[0,1].map(i=>`<td>${photos[i]?`<img src="${urls.get(photos[i].id)}" alt="${e(photos[i].caption||'ภาพหลักฐาน')}"/>`:'<div class="classic-photo-empty">ช่องภาพหลักฐานหน้างาน</div>'}</td>`).join('')}</tr></tbody></table><table class="classic-check-table"><thead><tr><th>ลำดับ</th><th>รายการตรวจสอบ</th><th>ผล</th><th>หมายเหตุ</th></tr></thead><tbody>${questions.map(([id,label],i)=>`<tr><td>${i+1}</td><td>${e(label)}</td><td>${e(({Y:'Y',N:'N',NONE:'None',NOT_TESTED:'ไม่ได้ตรวจ'})[p.answers[id]?.value]||'—')}</td><td>${e(p.answers[id]?.remark||'')}</td></tr>`).join('')}</tbody></table><div class="classic-legend"><b>หมายเหตุ</b><p>Y &nbsp; = &nbsp; Yes / ปกติ<br>N &nbsp; = &nbsp; No / ไม่ปกติ<br>None &nbsp; = &nbsp; ไม่มี / ไม่เกี่ยวข้อง<br>— &nbsp; = &nbsp; ยังไม่ได้บันทึก</p></div>`}
else if(s==='performance'){content=`<h2>Flow and Pressure Record</h2><table class="classic-performance"><thead><tr><th>FLOW VARIATION SPECIFIED</th><th>Rated</th>${p.tests.map(t=>`<th>${t.point}%</th>`).join('')}</tr></thead><tbody>${[['1. FLOW RATED (GPM)',p.ratedFlow,'flow'],['2. DISCHARGER PRESSURE (NAME PLATE)',p.ratedPressure,null],['3. DISCHARGER PRESSURE (PSI.)','—','discharge'],['4. SUCTION PRESSURE (PSI.)','—','suction']].map(([label,rated,k])=>`<tr><td>${label}</td><td>${e(rated??'ไม่ระบุ')}</td>${p.tests.map(t=>`<td>${k?(t.status==='NOT_TESTED'?'ไม่สามารถทดสอบได้':t.status==='TESTED'?e(t[k]??'—'):'—'):'ไม่ระบุ'}</td>`).join('')}</tr>`).join('')}</tbody></table><h3 class="classic-underlined">Fire Pump Engine Plates</h3><div class="classic-plates">${photos.filter(a=>a.category==='Fire Pump').slice(0,2).map(a=>`<img src="${urls.get(a.id)}" alt="${e(a.caption||a.name)}">`).join('')||'<div class="classic-photo-empty">รอภาพป้ายข้อมูลอุปกรณ์ของงานนี้</div>'}</div><div class="classic-curve">${chart(p)}</div><div class="classic-test-notes">${p.tests.filter(t=>t.status==='NOT_TESTED').map(t=>`<p>ไม่สามารถทดสอบที่ ${t.point}% : ${e(t.reason||'รอระบุเหตุผล')}</p>`).join('')}<p>ผลประเมินทางวิศวกรรม: รอผู้มีอำนาจตรวจทาน</p></div>`}
else if(s==='findings'){content=`<h2>สรุปผลและข้อเสนอแนะ</h2><h3>สรุปผลการตรวจสอบระบบเครื่องยนต์ดับเพลิง</h3><p class="classic-paragraph">${e(p.summary||'รอบันทึกสรุปผลการตรวจสอบของงานนี้')}</p><table class="classic-check-table"><thead><tr><th>ลำดับ</th><th>ข้อบกพร่องที่พบ</th><th>รายละเอียด</th></tr></thead><tbody>${questions.filter(([id])=>p.answers[id]?.value==='N').map(([id,label],i)=>`<tr><td>${i+1}</td><td>${e(label)}</td><td>${e(p.answers[id].remark||'รอรายละเอียด')}</td></tr>`).join('')||'<tr><td colspan="3">ยังไม่มีรายการข้อบกพร่องที่บันทึก — ไม่ใช่ผลรับรองว่าผ่าน</td></tr>'}</tbody></table><h3 style="margin-top:5cqw">ข้อเสนอแนะเพิ่มเติม</h3><p class="classic-paragraph">${e(p.notes||'ยังไม่ได้ระบุ')}</p>`}
else{content=`<h2>ภาพประกอบการตรวจสอบและบำรุงรักษา</h2><div class="classic-evidence">${photos.map(a=>`<figure><img src="${urls.get(a.id)}" alt="${e(a.caption||a.name)}"><figcaption>${e(a.caption||a.name)}</figcaption></figure>`).join('')||'<div class="classic-photo-empty">รอแนบรูปภาพหลักฐานของงานนี้</div>'}</div><p class="classic-paragraph">เอกสารสอบเทียบและเอกสารรับรองต้องแนบฉบับของงานนี้แยกต่างหาก</p>`}
return `<article class="paper classic-paper" data-template="${m.key}" aria-label="รายงานรูปแบบต้นฉบับ ${m.code}">${head}<div class="classic-content">${content}</div><footer class="classic-footer"><span>${pageNo||''}${total?' / '+total:''}</span><small>${code}</small></footer></article>`;
}
root.ClassicTemplates={meta,get,render};
})(typeof window!=='undefined'?window:globalThis);
